import 'package:flutter/material.dart';
import '../agent/task_manager.dart';
import '../theme/pro_theme.dart';
import '../widgets/pro_app_bar.dart';
class ProTaskManager extends StatefulWidget { const ProTaskManager({super.key}); @override State<ProTaskManager> createState()=>_ProTaskManagerState(); }
class _ProTaskManagerState extends State<ProTaskManager>{
 final _manager=TaskManager(); Future<void>? _loading; String _filter='All';
